 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);}
 void openCamera(){if(preview==null||binding||capture!=null)return;binding=true;int token=++generation;androidx.camera.view.PreviewView view=preview;status.setText("Camera…");com.google.common.util.concurrent.ListenableFuture<androidx.camera.lifecycle.ProcessCameraProvider> future=androidx.camera.lifecycle.ProcessCameraProvider.getInstance(this);future.addListener(()->{if(token!=generation||preview!=view)return;binding=false;try{provider=future.get();provider.unbindAll();androidx.camera.core.CameraSelector selector=front?androidx.camera.core.CameraSelector.DEFAULT_FRONT_CAMERA:androidx.camera.core.CameraSelector.DEFAULT_BACK_CAMERA;androidx.camera.core.Preview p=new androidx.camera.core.Preview.Builder().setTargetAspectRatio(androidx.camera.core.AspectRatio.RATIO_16_9).build();p.setSurfaceProvider(view.getSurfaceProvider());androidx.camera.video.Quality q=uhd?androidx.camera.video.Quality.UHD:androidx.camera.video.Quality.FHD;androidx.camera.video.Recorder rec=new androidx.camera.video.Recorder.Builder().setQualitySelector(androidx.camera.video.QualitySelector.from(q,androidx.camera.video.FallbackStrategy.lowerQualityOrHigherThan(q))).build();capture=androidx.camera.video.VideoCapture.withOutput(rec);provider.bindToLifecycle(this,selector,p,capture);status.setText(uhd?"● 4K auto":"● HD auto");}catch(Exception e){capture=null;status.setText("Camera non disponibile");toast(e.getMessage());}},androidx.core.content.ContextCompat.getMainExecutor(this));}
